{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(url, download_path=\"mnt/data/downloads/\"):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "url",
      "expression": "isinstance(url, str)",
      "description": "The URL to download from is provided as a string."
    },
    {
      "id": "P2",
      "target": "download_path",
      "expression": "isinstance(download_path, str)",
      "description": "The destination directory path is provided as a string."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "(not (download_succeeds(url) and response_content_type(url) != 'application/zip')) or (result == 'Error: The URL does not point to a ZIP file.')",
      "description": "If the downloaded response does not have content type application/zip, the function returns the specified incorrect file type error message."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "result == download_path or (isinstance(result, str) and result.startswith('Error: '))",
      "description": "The function returns the extraction directory path on success, or a descriptive error message beginning with 'Error: ' on failure."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "(not (download_succeeds(url) and response_content_type(url) == 'application/zip' and valid_zip_download(url))) or (result == download_path)",
      "description": "If the URL is reachable, the response content type is application/zip, and the downloaded bytes form a valid ZIP archive, the archive is extracted into download_path and the directory path is returned."
    },
    {
      "id": "Q4",
      "target": "return",
      "expression": "(not (network_error_or_invalid_url(url))) or (result == 'Error: Unable to download the file from the provided URL.')",
      "description": "If the URL cannot be reached or the file cannot be downloaded due to a request-related issue, the function returns the specified download error message."
    },
    {
      "id": "Q5",
      "target": "return",
      "expression": "archive_contains_project_directory(url, download_path)",
      "description": "If the response is identified as a ZIP file but the archive is corrupt or cannot be extracted, the function returns the specified corrupt ZIP error message."
    },
    {
      "id": "Q6",
      "target": "return",
      "expression": "(not (unexpected_exception_raised())) or (result.startswith('Error: ') and result != 'Error: Unable to download the file from the provided URL.' and result != 'Error: The URL does not point to a ZIP file.' and result != 'Error: The downloaded file is not a valid ZIP file.')",
      "description": "Any other exception is caught and returned as an error string formatted with the exception message."
    }
  ],
  "invariants": [
    {
      "id": "I1",
      "target": "state",
      "expression": "input_not_modified(url)",
      "description": "The URL argument is not modified by the function."
    },
    {
      "id": "I2",
      "target": "state",
      "expression": "input_not_modified(download_path)",
      "description": "The download_path argument value is not modified by the function."
    }
  ]
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(s1, s2):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "s1",
      "expression": "isinstance(s1, pd.Series) and isinstance(s2, pd.Series)",
      "description": "Both inputs are pandas Series to be compared in the swarm plot."
    },
    {
      "id": "P2",
      "target": "name",
      "expression": "s1.name is not None and s2.name is not None and s1.name != s2.name",
      "description": "Each Series has a distinct name used to identify it in the plot."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "is_swarm_plot_axes(result[0], series_names=[s1.name, s2.name], values=list(s1) + list(s2))",
      "description": "The returned Axes contains a swarm plot visualizing the values from both Series, grouped by their Series names."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "result[1] == len(set(s1).intersection(set(s2)))",
      "description": "The returned intersection count equals the number of unique data values present in both Series."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "has_red_dashed_intersection_lines(result[0], set(s1).intersection(set(s2)))",
      "description": "The plot highlights each unique intersecting data value with a red dashed line at that value."
    }
  ],
  "invariants": [
    {
      "id": "I1",
      "target": "state",
      "expression": "input_not_modified(s1)",
      "description": "The first input Series is not modified by the function."
    },
    {
      "id": "I2",
      "target": "state",
      "expression": "input_not_modified(s2)",
      "description": "The second input Series is not modified by the function."
    }
  ]
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(students, subjects, seed=None):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "students",
      "expression": "isinstance(students, list) and all(isinstance(student, str) for student in students)",
      "description": "students is a list of student names represented as strings."
    },
    {
      "id": "P2",
      "target": "subjects",
      "expression": "isinstance(subjects, list) and all(isinstance(subject, str) for subject in subjects)",
      "description": "subjects is a list of subject names represented as strings."
    },
    {
      "id": "P3",
      "target": "seed",
      "expression": "seed is None or isinstance(seed, int)",
      "description": "seed is either None or an integer usable to seed the random number generator."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "list(result.columns) == ['Student'] + subjects + ['Average Grade']",
      "description": "The DataFrame columns consist of the student name column, one column for each subject in the same order as provided, and an average grade column."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "len(result) == len(students)",
      "description": "The DataFrame contains one row for each input student."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "result['Student'].tolist() == students",
      "description": "The Student column preserves the input students in their original order."
    },
    {
      "id": "Q4",
      "target": "return",
      "expression": "all(is_generated_grade(result.loc[i, subject]) for i in range(len(students)) for subject in subjects)",
      "description": "Each subject cell contains a randomly generated grade for the corresponding student and subject."
    },
    {
      "id": "Q5",
      "target": "return",
      "expression": "all(result.loc[i, 'Average Grade'] == statistics.mean([result.loc[i, subject] for subject in subjects]) for i in range(len(students)))",
      "description": "Each Average Grade value is the arithmetic mean of that student's generated subject grades."
    },
    {
      "id": "Q6",
      "target": "return",
      "expression": "seed is None or repeated_call_returns_equal_dataframe(task_func, students, subjects, seed, result)",
      "description": "When a seed is provided, calling the function again with the same students, subjects, and seed produces an equivalent DataFrame."
    }
  ],
  "invariants": [
    {
      "id": "I1",
      "target": "state",
      "expression": "input_not_modified(students)",
      "description": "The input students list is not modified."
    },
    {
      "id": "I2",
      "target": "state",
      "expression": "input_not_modified(subjects)",
      "description": "The input subjects list is not modified."
    }
  ]
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func():"
  },
  "preconditions": [],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "dataframe_matches_category_value_pairs(result[0], list_of_pairs)",
      "description": "Each 'Moving Average' value is the arithmetic mean of the current random number and up to the previous five random numbers."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "all(isinstance(x, (int, np.integer)) and 0 <= x <= RANGE for x in result['Random Numbers'])",
      "description": "The 'Random Numbers' column is filled with randomly generated integers within the configured inclusive range."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "len(plt.gca().patches) > 0",
      "description": "A matplotlib histogram has been drawn for the generated random numbers."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(df, target):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "df",
      "expression": "isinstance(df, pd.DataFrame)",
      "description": "df must be a pandas DataFrame."
    },
    {
      "id": "P2",
      "target": "input",
      "expression": "target in df.columns",
      "description": "target must name an existing column in df."
    },
    {
      "id": "P3",
      "target": "df",
      "expression": "len(df) >= 2",
      "description": "df must contain at least two rows for regression scoring."
    },
    {
      "id": "P4",
      "target": "input",
      "expression": "df.shape[1] >= 2",
      "description": "df must contain at least one feature column in addition to the target column."
    },
    {
      "id": "P5",
      "target": "input",
      "expression": "all(pd.api.types.is_numeric_dtype(df[col]) for col in df.columns)",
      "description": "all DataFrame columns must be numeric so they can be used by LinearRegression."
    },
    {
      "id": "P6",
      "target": "input",
      "expression": "not df.isnull().to_numpy().any()",
      "description": "df must not contain missing values."
    },
    {
      "id": "P7",
      "target": "input",
      "expression": "df.drop(columns=[target]).shape[1] >= 1",
      "description": "there must be at least one predictor feature after removing the target column."
    },
    {
      "id": "P8",
      "target": "input",
      "expression": "df.drop(columns=[target]).to_numpy().shape[0] == df[target].to_numpy().shape[0]",
      "description": "feature matrix and target vector must have the same number of samples."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "result == LinearRegression().fit(df.drop(columns=[target]), df[target]).score(df.drop(columns=[target]), df[target])",
      "description": "the returned score equals the R-squared score of a LinearRegression model fitted on all non-target columns to predict the target column."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "result <= 1.0",
      "description": "the returned R-squared score must not exceed 1.0."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "not pd.isna(result)",
      "description": "the returned score must not be NaN."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(sentence):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "sentence",
      "expression": "isinstance(sentence, str)",
      "description": "sentence must be a string so that regular-expression word extraction can be applied."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "result == dict(Counter(re.findall(r'\\w+', sentence)))",
      "description": "The returned dictionary maps each regex-extracted word token in sentence to the number of times that token occurs."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "set(result.keys()) == set(re.findall(r'\\w+', sentence))",
      "description": "Every key in the result is a word token found in the sentence, and every found word token appears as a key."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "all(result[word] == re.findall(r'\\w+', sentence).count(word) for word in result)",
      "description": "Each value is the exact occurrence count of its corresponding word token, preserving case and token spelling as extracted."
    },
    {
      "id": "Q4",
      "target": "return",
      "expression": "result == {} if re.findall(r'\\w+', sentence) == [] else True",
      "description": "If the sentence contains no regex word tokens, the function returns an empty dictionary."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(directory=DIRECTORY_PATH, from_encoding='cp1251', to_encoding='utf8'):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "directory",
      "expression": "isinstance(directory, (str, bytes, os.PathLike))",
      "description": "The directory argument is a path-like value accepted by os.path.join and glob.glob."
    },
    {
      "id": "P2",
      "target": "input",
      "expression": "codecs.lookup(from_encoding) is not None and codecs.lookup(to_encoding) is not None",
      "description": "Both source and target encoding names are recognized by Python's codec registry."
    },
    {
      "id": "P3",
      "target": "input",
      "expression": "all(is_decodable_with_encoding(path, from_encoding) for path in glob.glob(os.path.join(directory, '*.txt')))",
      "description": "Every matched .txt file contains bytes that can be decoded using the source encoding."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "all(file_text_after(path, to_encoding) == file_text_before(path, from_encoding) for path in glob.glob(os.path.join(directory, '*.txt')))",
      "description": "Every .txt file directly matched in the specified directory is overwritten so that decoding it with the target encoding yields the same text that decoding its original bytes with the source encoding yielded."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "result is None",
      "description": "The function returns None after completing the in-place conversion."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "all(file_bytes_after(path) == file_bytes_before(path) for path in files_not_matching_glob_before(directory, '*.txt'))",
      "description": "Files in the specified directory that were not matched by the .txt glob pattern before execution are not modified."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(data, n_clusters=3):"
  },
  "preconditions": [],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "dataframe_matches_category_value_pairs(result[0], data)",
      "description": "The function raises ValueError when data is not a pandas DataFrame."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "dataframe_matches_category_value_pairs(result[0], data)",
      "description": "The function raises ValueError when n_clusters is not an integer greater than 1."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "isinstance(result[0], np.ndarray)",
      "description": "For valid inputs, the first returned value is a NumPy array of cluster labels."
    },
    {
      "id": "Q4",
      "target": "return",
      "expression": "result[0].shape == (len(data),)",
      "description": "For valid inputs, the labels array contains exactly one label for each row in data."
    },
    {
      "id": "Q5",
      "target": "return",
      "expression": "set(result[0].tolist()).issubset(set(range(n_clusters)))",
      "description": "For valid inputs, every returned label is a cluster identifier in the range 0 through n_clusters - 1."
    },
    {
      "id": "Q6",
      "target": "return",
      "expression": "isinstance(result[1], plt.Axes)",
      "description": "For valid inputs, the second returned value is a matplotlib Axes object."
    },
    {
      "id": "Q7",
      "target": "return",
      "expression": "len([collection for collection in result[1].collections if isinstance(collection, PathCollection)]) >= 2",
      "description": "For valid inputs, the Axes contains scatter plot collections visualizing the clustered samples and the centroids."
    },
    {
      "id": "Q8",
      "target": "return",
      "expression": "kmeans_was_fit_with_n_clusters(data, n_clusters, result[0])",
      "description": "For valid inputs, the labels are produced by fitting KMeans with the requested number of clusters to the provided dataset."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func():"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "input",
      "expression": "module_is_importable('warnings')",
      "description": "The Python warnings module is available for configuring and capturing warnings."
    },
    {
      "id": "P2",
      "target": "input",
      "expression": "module_is_importable('sklearn.model_selection')",
      "description": "scikit-learn model selection utilities are available for splitting the iris dataset."
    },
    {
      "id": "P3",
      "target": "input",
      "expression": "module_is_importable('sklearn.svm')",
      "description": "scikit-learn SVM utilities are available for training the classifier."
    },
    {
      "id": "P4",
      "target": "input",
      "expression": "module_is_importable('sklearn.datasets')",
      "description": "scikit-learn dataset utilities are available for loading the iris dataset."
    },
    {
      "id": "P5",
      "target": "input",
      "expression": "module_is_importable('sklearn.metrics')",
      "description": "scikit-learn metrics utilities are available for computing classification accuracy."
    },
    {
      "id": "P6",
      "target": "input",
      "expression": "iris_dataset_available()",
      "description": "The iris dataset can be loaded and contains feature data and target labels suitable for supervised classification."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "result[0] == accuracy_score_for_svm_on_iris_test_split(test_size=0.33)",
      "description": "The returned accuracy equals the accuracy score computed from SVM predictions on the held-out iris test split."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "isinstance(result[0], float)",
      "description": "The first tuple element is the computed SVM classification accuracy as a float."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "0.0 <= result[0] <= 1.0",
      "description": "The returned accuracy is a valid classification accuracy in the inclusive range from 0.0 to 1.0."
    },
    {
      "id": "Q4",
      "target": "return",
      "expression": "result[1] is None or isinstance(result[1], str)",
      "description": "The second tuple element is either None when no warning is needed or a string containing the warning message."
    },
    {
      "id": "Q5",
      "target": "return",
      "expression": "train_test_split_uses_test_size(0.33)",
      "description": "The iris dataset is split into training and test sets using a test size of 0.33."
    },
    {
      "id": "Q6",
      "target": "return",
      "expression": "svm_classifier_is_fitted_on_training_split()",
      "description": "An SVM classifier is trained using the training portion of the iris dataset."
    },
    {
      "id": "Q7",
      "target": "return",
      "expression": "warnings_filter_action_is_set('always')",
      "description": "The warning filter action is configured to always emit matching warnings."
    },
    {
      "id": "Q8",
      "target": "return",
      "expression": "(result[0] < 0.9 and isinstance(result[1], str) and len(result[1]) > 0) or (result[0] >= 0.9 and result[1] is None)",
      "description": "A non-empty warning message is returned exactly when the accuracy is below 0.9; otherwise the warning message is None."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(l, x_data, plot=False):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "l",
      "expression": "len(l) == len(x_data)",
      "description": "The y-values and x-values must be paired elementwise with the same number of observations."
    },
    {
      "id": "P2",
      "target": "l",
      "expression": "len(l) >= 3",
      "description": "At least three observations are required to estimate the three coefficients of a quadratic curve with scipy.optimize.curve_fit."
    },
    {
      "id": "P3",
      "target": "input",
      "expression": "all_finite_numeric(l) and all_finite_numeric(x_data)",
      "description": "Both input sequences must contain only finite numeric values suitable for numerical curve fitting."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "(not plot) or axes_contains_points_and_curve(result[2], x_data, l, x_data, result[1])",
      "description": "When plot is True, the returned Axes contains the original data points and the fitted quadratic curve values."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "len(result[0]) == 3",
      "description": "The returned params array contains the three coefficients of the fitted quadratic model a*x**2 + b*x + c."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "len(result[1]) == len(x_data)",
      "description": "The fitted_values array has exactly one fitted y-value for each input x_data element."
    },
    {
      "id": "Q4",
      "target": "return",
      "expression": "array_allclose(result[1], quadratic_values(result[0], x_data))",
      "description": "Each fitted value is computed by evaluating the fitted quadratic model with the returned parameters at the corresponding x_data value."
    },
    {
      "id": "Q5",
      "target": "return",
      "expression": "least_squares_quadratic_fit(result[0], x_data, l)",
      "description": "The returned parameters minimize the quadratic least-squares residuals for l as a function of x_data, subject to scipy.optimize.curve_fit behavior."
    },
    {
      "id": "Q6",
      "target": "return",
      "expression": "(not plot) or is_matplotlib_axes(result[2])",
      "description": "When plot is True, the third returned element is a matplotlib Axes object."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(n_samples=100, centers=3, n_features=2, random_seed=42):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "n_features",
      "expression": "isinstance(n_features, int) and n_features >= 2",
      "description": "n_features must be an integer of at least 2 so the generated data can be plotted using the first two feature columns."
    },
    {
      "id": "P2",
      "target": "random_seed",
      "expression": "isinstance(random_seed, int) or random_seed is None",
      "description": "random_seed must be an integer seed or None for sklearn's random_state parameter."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "hasattr(result[1], 'shape') and result[1].shape == (n_samples,)",
      "description": "The returned y array contains exactly one cluster label for each generated sample."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "hasattr(result[0], 'shape') and result[0].shape == (n_samples, n_features)",
      "description": "The returned X array has one row per generated sample and one column per requested feature."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "set(result[1].tolist()).issubset(set(range(centers))) and len(set(result[1].tolist())) <= centers",
      "description": "The returned labels are valid blob cluster indices for the requested number of centers."
    },
    {
      "id": "Q4",
      "target": "return",
      "expression": "hasattr(result[2], 'scatter') and len(result[2].collections) >= 1",
      "description": "The returned Axes object contains at least one scatter-plot collection visualizing the generated blob points."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(df1, df2, column1=\"feature1\", column2=\"feature2\"):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "input",
