    },
    {
      "id": "P4",
      "target": "g",
      "expression": "all(isinstance(g, str) for g in possible_grades)",
      "description": "Every possible grade is a string so it can be compared case-insensitively with submitted grades."
    },
    {
      "id": "P5",
      "target": "list",
      "expression": "len(list(possible_grades)) == len({g.upper() for g in possible_grades})",
      "description": "possible_grades contains no duplicate grade categories after case normalization, ensuring one output row per category."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "sum(result[0]['Count']) == sum(1 for sg in student_grades if sg.upper() in {g.upper() for g in possible_grades})",
      "description": "The total reported count includes only submitted grades that match a possible grade case-insensitively; nonmatching grades are ignored."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "isinstance(result[0], pd.DataFrame)",
      "description": "The first returned value is a pandas DataFrame."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "list(result[0].columns) == ['Count']",
      "description": "The DataFrame has exactly one column named 'Count'."
    },
    {
      "id": "Q4",
      "target": "return",
      "expression": "result[0].index.name == 'Grade'",
      "description": "The DataFrame index is named 'Grade'."
    },
    {
      "id": "Q5",
      "target": "return",
      "expression": "list(result[0].index) == list(possible_grades)",
      "description": "The DataFrame includes all possible grades as index entries in the same order supplied by possible_grades."
    },
    {
      "id": "Q6",
      "target": "return",
      "expression": "all(result[0].loc[g, 'Count'] == sum(1 for sg in student_grades if sg.upper() == g.upper()) for g in possible_grades)",
      "description": "Each count equals the number of submitted grades matching that possible grade case-insensitively, without stripping or otherwise altering whitespace."
    },
    {
      "id": "Q7",
      "target": "return",
      "expression": "isinstance(result[1], matplotlib.axes.Axes)",
      "description": "The second returned value is a matplotlib Axes object."
    },
    {
      "id": "Q8",
      "target": "return",
      "expression": "result[1].get_title() == 'Grade Distribution'",
      "description": "The bar chart title is 'Grade Distribution'."
    },
    {
      "id": "Q9",
      "target": "return",
      "expression": "result[1].get_xlabel() == 'Grade'",
      "description": "The bar chart x-axis label is 'Grade'."
    },
    {
      "id": "Q10",
      "target": "return",
      "expression": "result[1].get_ylabel() == 'Number of Students'",
      "description": "The bar chart y-axis label is 'Number of Students'."
    }
  ],
  "invariants": [
    {
      "id": "I1",
      "target": "state",
      "expression": "all(sg.upper() == pg.upper() or sg != pg for sg in student_grades for pg in possible_grades)",
      "description": "Grade matching is case-insensitive while retaining the original string content for whitespace-sensitive distinctions."
    },
    {
      "id": "I2",
      "target": "state",
      "expression": "set(result[0].index) == set(possible_grades)",
      "description": "The report always contains exactly the supplied possible grade categories, regardless of whether their counts are zero."
    }
  ]
}

